#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define MAX_ATTEMPTS 7U
#define MIN_TARGET 1
#define MAX_TARGET 100

enum GuessResult {
    GUESS_INVALID,
    GUESS_LOW,
    GUESS_HIGH,
    GUESS_CORRECT,
    GUESS_OUT_OF_ATTEMPTS
};

struct Game {
    int target;
    size_t attempts;
    bool finished;
    bool won;
};

static bool game_init(struct Game *game, int target)
{
    if (game == NULL || target < MIN_TARGET || target > MAX_TARGET) {
        return false;
    }
    game->target = target;
    game->attempts = 0U;
    game->finished = false;
    game->won = false;
    return true;
}

static enum GuessResult game_guess(struct Game *game, int guess)
{
    if (game == NULL || game->finished ||
        guess < MIN_TARGET || guess > MAX_TARGET) {
        return GUESS_INVALID;
    }

    if (game->attempts == MAX_ATTEMPTS) {
        return GUESS_OUT_OF_ATTEMPTS;
    }

    ++game->attempts;
    if (guess < game->target) return GUESS_LOW;
    if (guess > game->target) return GUESS_HIGH;

    game->finished = true;
    game->won = true;
    return GUESS_CORRECT;
}

static bool check(bool condition, const char *message)
{
    if (!condition) {
        printf("FAIL: %s\n", message);
        return false;
    }
    return true;
}

int main(void)
{
    struct Game game;

    if (!check(game_init(&game, 37), "initialise fixed target")) return 1;
    if (!check(game_guess(&game, 20) == GUESS_LOW, "low guess")) return 1;
    if (!check(game_guess(&game, 50) == GUESS_HIGH, "high guess")) return 1;
    if (!check(game.attempts == 2U, "two valid attempts counted")) return 1;
    if (!check(game_guess(&game, 37) == GUESS_CORRECT, "correct guess")) return 1;
    if (!check(game.finished && game.won, "winning state")) return 1;
    if (!check(game_guess(&game, 37) == GUESS_INVALID,
               "reject guess after round finished")) return 1;

    if (!check(game_init(&game, 1), "initialise lower boundary target")) return 1;
    if (!check(game_guess(&game, 1) == GUESS_CORRECT,
               "guess lower boundary")) return 1;

    if (!check(game_init(&game, 100), "initialise upper boundary target")) return 1;
    if (!check(game_guess(&game, 100) == GUESS_CORRECT,
               "guess upper boundary")) return 1;

    if (!check(game_init(&game, 60), "initialise attempt-limit target")) return 1;
    for (size_t i = 0U; i < MAX_ATTEMPTS; ++i) {
        if (!check(game_guess(&game, 1) == GUESS_LOW,
                   "valid wrong guess before limit")) return 1;
    }
    if (!check(game.attempts == MAX_ATTEMPTS, "attempt limit reached")) return 1;
    if (!check(game_guess(&game, 2) == GUESS_OUT_OF_ATTEMPTS,
               "reject guess after attempt limit")) return 1;

    if (!check(!game_init(&game, 0), "reject target below range")) return 1;
    if (!check(!game_init(&game, 101), "reject target above range")) return 1;

    puts("All deterministic game tests passed.");
    return 0;
}

#include <ctype.h>
#include <errno.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INPUT_SIZE 128U
#define MIN_TARGET 1L
#define MAX_TARGET 100L
#define MAX_ATTEMPTS 7U

enum ReadStatus {
    READ_OK,
    READ_EOF,
    READ_TOO_LONG
};

static enum ReadStatus read_line(char buffer[INPUT_SIZE])
{
    if (fgets(buffer, (int)INPUT_SIZE, stdin) == NULL) {
        return READ_EOF;
    }

    char *newline = NULL;
    for (char *p = buffer; *p != '\0'; ++p) {
        if (*p == '\n') {
            newline = p;
            break;
        }
    }

    if (newline != NULL) {
        *newline = '\0';
        return READ_OK;
    }

    if (feof(stdin)) return READ_OK;

    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {
        /* Discard the rest of an overlong line. */
    }
    return READ_TOO_LONG;
}

static bool parse_guess(const char *line, int *guess)
{
    char *end = NULL;
    errno = 0;
    long value = strtol(line, &end, 10);

    if (end == line || errno == ERANGE) return false;

    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0' || value < MIN_TARGET || value > MAX_TARGET) {
        return false;
    }

    *guess = (int)value;
    return true;
}

static int make_target(void)
{
    return (int)(rand() % 100) + 1;
}

static bool play_round(int target)
{
    char line[INPUT_SIZE];
    size_t attempts = 0U;

    printf("I have selected a number from %d to %d.\n",
           (int)MIN_TARGET, (int)MAX_TARGET);
    printf("You have %u valid guesses.\n", (unsigned int)MAX_ATTEMPTS);

    while (attempts < MAX_ATTEMPTS) {
        int guess = 0;
        printf("Guess %u/%u: ", (unsigned int)(attempts + 1U),
               (unsigned int)MAX_ATTEMPTS);
        fflush(stdout);

        enum ReadStatus status = read_line(line);
        if (status == READ_EOF) return false;
        if (status == READ_TOO_LONG) {
            puts("Input too long; this does not use an attempt.");
            continue;
        }

        if (!parse_guess(line, &guess)) {
            puts("Enter one whole number from 1 to 100. No attempt used.");
            continue;
        }

        ++attempts;
        if (guess < target) {
            puts("Too low.");
        } else if (guess > target) {
            puts("Too high.");
        } else {
            printf("Correct! You won in %u valid guesses.\n",
                   (unsigned int)attempts);
            return true;
        }
    }

    printf("No attempts left. The number was %d.\n", target);
    return true;
}

int main(void)
{
    char line[INPUT_SIZE];
    srand((unsigned int)time(NULL));

    puts("Number Guessing Game");
    puts("Guess the number from 1 to 100.");

    for (;;) {
        if (!play_round(make_target())) {
            puts("\nInput ended. Goodbye.");
            break;
        }

        fputs("Play again? (y/n): ", stdout);
        fflush(stdout);

        enum ReadStatus status = read_line(line);
        if (status == READ_EOF) {
            puts("\nGoodbye.");
            break;
        }
        if (status == READ_TOO_LONG) {
            puts("Response too long. Exiting.");
            break;
        }

        const char *answer = line;
        while (isspace((unsigned char)*answer)) ++answer;

        if (*answer == 'n' || *answer == 'N') {
            puts("Thanks for playing.");
            break;
        }
        if (*answer == 'y' || *answer == 'Y') {
            continue;
        }

        puts("Unrecognised response. Exiting.");
        break;
    }

    return 0;
}
